const ship = document.querySelector("#ship");
const STEP = 20;
const MAX_X = 270; // alan 300px, gemi 30px genişliğinde
let x = 0;

// Bip sesi (hazır): ses çalamazsa oyun sessizce devam eder
let audio = null;
function beep(freq = 440) {
  try {
    audio = audio || new AudioContext();
    const osc = audio.createOscillator();
    const gain = audio.createGain();
    osc.frequency.value = freq;
    gain.gain.value = 0.05;
    osc.connect(gain);
    gain.connect(audio.destination);
    osc.start();
    osc.stop(audio.currentTime + 0.1);
  } catch (err) {
    // ses yoksa sorun değil
  }
}

function moveShip(dx) {
  // x'i değiştir, 0 ile MAX_X arasında tut, gemiyi yerleştir
  x = x + dx;
  if (x < 0 || x > MAX_X) beep(220); // duvara çarptı
  x = Math.max(0, Math.min(MAX_X, x));
  ship.style.left = x + "px";
}

// keydown dinle
document.addEventListener("keydown", (e) => {
  if (e.target.tagName === "INPUT") return;
  if (e.key === "ArrowLeft") {
    e.preventDefault();
    moveShip(-STEP);
  } else if (e.key === "ArrowRight") {
    e.preventDefault();
    moveShip(STEP);
  }
});

check.js:
key("ArrowRight");
key("ArrowRight");
key("ArrowRight");
assert(x === 60, "Üç kez sağ oka basınca x 60 olmalı.");
assert(ship.style.left === "60px", "Gemi style.left ile 60px'e taşınmalı.");
for (let i = 0; i < 5; i++) key("ArrowLeft");
assert(x === 0 && ship.style.left === "0px", "Gemi 0'ın soluna çıkmamalı.");
