const search = document.querySelector("#search");

// keydown dinle
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && e.target === search) {
    search.value = "";
    search.blur();
    return;
  }
  if (e.target.tagName === "INPUT") return; // yazı yazılıyor
  if (e.key === "t") {
    document.body.classList.toggle("dark");
  } else if (e.key === "/") {
    e.preventDefault();
    search.focus();
  }
});

check.js:
key("t");
assert(document.body.classList.contains("dark"), "'t' tuşu body'ye dark sınıfını eklemeli.");
key("t");
assert(!document.body.classList.contains("dark"), "'t' tuşuna tekrar basınca dark sınıfı kalkmalı.");
key("/");
assert(document.activeElement === $("#search"), "'/' tuşu arama kutusuna odaklanmalı (search.focus()).");
key("t", "#search");
assert(!document.body.classList.contains("dark"), "Arama kutusuna yazarken 't' temayı değiştirmemeli.");
type("#search", "oyun");
key("Escape", "#search");
assert($("#search").value === "", "Arama kutusunda Escape kutuyu boşaltmalı.");
assert(document.activeElement !== $("#search"), "Escape'ten sonra arama kutusu odaktan çıkmalı (blur).");

