answered = false;
key("3");
assert(feedback.textContent.startsWith("Yanlış") && score === 10, "'3' tuşu 3. seçeneği seçmeli (yanlış cevap).");
answered = false;
key("1");
assert(feedback.textContent.startsWith("Yanlış") && score === 10, "'1' tuşu 1. seçeneği seçmeli (yanlış cevap).");
